const aPriv = crypto.createPrivateKey(A_PRIV);
const bPriv = crypto.createPrivateKey(B_PRIV);
const bPub = crypto.createPublicKey(B_PUB);

const ab = crypto.diffieHellman({ privateKey: aPriv, publicKey: bPub });
const ba = crypto.diffieHellman({ privateKey: bPriv, publicKey: aPriv });
console.log("fixed", ab.length, ab.toString("base64"), ab.equals(ba));

const attempt = (label, der) => {
  try {
    const pub = crypto.createPublicKey({ key: Buffer.from(der, "base64"), format: "der", type: "spki" });
    console.log(label, "import", pub.asymmetricKeyType);
    try {
      crypto.diffieHellman({ privateKey: aPriv, publicKey: pub });
      console.log(label, "derive ok");
    } catch (e) {
      console.log(label, "derive THROW", e.name, e.code, e.message);
    }
  } catch (e) {
    console.log(label, "import THROW", e.name, e.code, e.message);
  }
};
attempt("y=1", "");
attempt("y=p-1", "");
attempt("y=p-2", "");
attempt("y=2", "");
attempt("y=3", "");
